// Dane z webhooka są w $json.body - spłaszczamy je, żeby dalej używać $json.pole
const src = $json.body && typeof $json.body === 'object' ? $json.body : $json;
const required = ["name","phone","date","guests","type"];
const missing = required.filter((k) => src[k] === undefined || src[k] === null || String(src[k]).trim() === '');
if (missing.length) {
  throw new Error('Brak wymaganych pól: ' + missing.join(', '));
}
const clean = {};
for (const [k, v] of Object.entries(src)) {
  clean[k] = typeof v === 'string' ? v.trim().slice(0, 5000) : v;
}
if (clean.email !== undefined && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(clean.email))) {
  throw new Error('Niepoprawny adres e-mail');
}
return { json: { ...clean, _odebrano: new Date().toISOString() } };

let tel = String($json.phone || '').replace(/[\s()-]/g, '');
if (/^\d{9}$/.test(tel)) tel = '+48' + tel;
if (!/^\+\d{10,15}$/.test(tel)) throw new Error('Niepoprawny numer telefonu');
const d = new Date($json.date);
if (isNaN(d) || d < new Date()) throw new Error('Niepoprawna lub przeszła data');
const goscie = Number($json.guests);
if (!Number.isInteger(goscie) || goscie < 1 || goscie > 2000) throw new Error('Niepoprawna liczba gości');
return { json: { ...$json, phone: tel, guests: goscie,
  dataTekst: d.toLocaleDateString('pl-PL', { timeZone: 'Europe/Warsaw', dateStyle: 'full' }),
  numerZgloszenia: 'ZAP-' + Date.now().toString(36).toUpperCase() } };

